-- SYNTHETIC sample data for local development (pipeline/tests/fake_dump.py; rank history is a random walk). Not real VNDB data.
-- VNDB Ranking+ snapshot (generated by pipeline/vndb_rank)
DROP TABLE IF EXISTS vn__next;
CREATE TABLE vn__next (
  id           INTEGER PRIMARY KEY,   -- VNDB id without the "v" prefix
  idx          INTEGER NOT NULL,      -- position in this snapshot (voter shards / user votes refer to it)
  title        TEXT    NOT NULL,      -- title in the original language
  latin        TEXT,
  title_ja     TEXT,
  title_zh     TEXT,
  title_en     TEXT,
  olang        TEXT,
  released     INTEGER,               -- YYYYMMDD (MM/DD may be 99)
  dev_id       INTEGER,
  image        INTEGER,               -- cover id (cv...)
  image_sexual REAL,                  -- 0 safe .. 2 explicit
  length       INTEGER,
  votes        INTEGER NOT NULL,      -- VNDB vote count
  rating       REAL,                  -- VNDB Bayesian rating, 1-10
  average      REAL,
  search       TEXT    NOT NULL,
  trend        INTEGER,               -- rank change of the default method over ~7 days
  ranks        TEXT    NOT NULL,      -- JSON {method: [rank, score]}
  neighbors    TEXT    NOT NULL,      -- JSON [[vid, wins, losses, common], ...]
  relations    TEXT    NOT NULL,      -- JSON [[vid, relation], ...]
  analysis     TEXT    NOT NULL,      -- JSON, see analysis.py
  similar      TEXT    NOT NULL,      -- JSON [[vid, similarity, common], ...]
  history      TEXT    NOT NULL       -- JSON [[day, rank, vndb_rank], ...], day = days since 2000-01-01
);
DROP TABLE IF EXISTS producer__next;
CREATE TABLE producer__next (
  id     INTEGER PRIMARY KEY,
  name   TEXT NOT NULL,
  latin  TEXT
);
DROP TABLE IF EXISTS user_block__next;
CREATE TABLE user_block__next (
  shard INTEGER NOT NULL,  -- uid % 2048
  part  INTEGER NOT NULL,
  data  TEXT    NOT NULL,  -- JSON {uid: {name, votes, similar, recs}}
  PRIMARY KEY (shard, part)
) WITHOUT ROWID;
DROP TABLE IF EXISTS user_name__next;
CREATE TABLE user_name__next (
  shard INTEGER NOT NULL,  -- fnv1a(lower(name)) % 64
  part  INTEGER NOT NULL,
  data  TEXT    NOT NULL,  -- JSON {lower(name): uid}
  PRIMARY KEY (shard, part)
) WITHOUT ROWID;
DROP TABLE IF EXISTS vn_voters__next;
CREATE TABLE vn_voters__next (
  shard INTEGER NOT NULL,  -- vn idx % 1024
  part  INTEGER NOT NULL,
  data  BLOB    NOT NULL,  -- segments (idx u16, n u32) + n x (uid u32, vote u8, sp decile u8), see storage.voter_shards
  PRIMARY KEY (shard, part)
) WITHOUT ROWID;
DROP TABLE IF EXISTS vn_notes__next;
CREATE TABLE vn_notes__next (
  shard INTEGER NOT NULL,  -- vn idx % 512
  part  INTEGER NOT NULL,
  data  TEXT    NOT NULL,  -- JSON [[idx, uid, name, vote, date, text, has_page], ...], newest first per VN
  PRIMARY KEY (shard, part)
) WITHOUT ROWID;
DROP TABLE IF EXISTS user_notes__next;
CREATE TABLE user_notes__next (
  shard INTEGER NOT NULL,  -- uid % 1024
  part  INTEGER NOT NULL,
  data  TEXT    NOT NULL,  -- JSON [[uid, idx, vote, date, text], ...]
  PRIMARY KEY (shard, part)
) WITHOUT ROWID;
DROP TABLE IF EXISTS doc__next;
CREATE TABLE doc__next (
  key   TEXT    NOT NULL,  -- "catalogue", "ranks:<method>"
  part  INTEGER NOT NULL,
  data  TEXT    NOT NULL,  -- a prebuilt JSON response, split into parts
  PRIMARY KEY (key, part)
) WITHOUT ROWID;
DROP TABLE IF EXISTS meta__next;
CREATE TABLE meta__next (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL      -- JSON
) WITHOUT ROWID;
DROP TABLE IF EXISTS vn;
ALTER TABLE vn__next RENAME TO vn;
DROP TABLE IF EXISTS producer;
ALTER TABLE producer__next RENAME TO producer;
DROP TABLE IF EXISTS user_block;
ALTER TABLE user_block__next RENAME TO user_block;
DROP TABLE IF EXISTS user_name;
ALTER TABLE user_name__next RENAME TO user_name;
DROP TABLE IF EXISTS vn_voters;
ALTER TABLE vn_voters__next RENAME TO vn_voters;
DROP TABLE IF EXISTS vn_notes;
ALTER TABLE vn_notes__next RENAME TO vn_notes;
DROP TABLE IF EXISTS user_notes;
ALTER TABLE user_notes__next RENAME TO user_notes;
DROP TABLE IF EXISTS doc;
ALTER TABLE doc__next RENAME TO doc;
DROP TABLE IF EXISTS meta;
ALTER TABLE meta__next RENAME TO meta;
